{"file":"tester.c","content":"#include <stdio.h>
#include <stdlib.h>

int main() {
    int n, i, search, low, high, mid;
    int arr[100];

    // Get array size
    printf("Enter number of elements: ");
    scanf("%d", &n);

    // Get array elements
    printf("Enter %d integers:\n", n);
    for (i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }

    // Sort array
    for (i = 0; i < n-1; i++) {
        for (int j = 0; j < n-i-1; j++) {
            if (arr[j] > arr[j+1]) {
                int temp = arr[j];
                arr[j] = arr[j+1];
                arr[j+1] = temp;
            }
        }
    }

    // Get search element
    printf("Enter element to search: ");
    scanf("%d", &search);

    // Binary search
    low = 0;
    high = n - 1;
    int found = 0;
    while (low <= high) {
        mid = (low + high) / 2;
        if (arr[mid] == search) {
            printf("Element found at position %d\n", mid+1);
            found = 1;
            break;
        } else if (arr[mid] < search) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }

    if (!found) {
        printf("Element not found\n");
    }

    return 0;
}"}

